const PALETTE = {
  'space-deep': 0x20283D,
  'shadow-plum': 0x765768,
  'regolith-mid': 0xB95C40,
  'regolith-light': 0xE6A26A,
  'structure-white': 0xF2E5D2,
  'structure-gray': 0x686976,
  'trim-dark': 0x303240,
  'accent-orange': 0xFF8A24,
  'accent-cyan': 0x54E5F5,
  'accent-blue': 0x35CFFF,
  'glass-tint': 0xEBD9C5,
  'cell-blue': 0x2F58B8,
  'grow-magenta': 0xE040FB,
  'plant-green': 0x5A9E58,
  'ice-pale': 0xD8EEF8
};

const BUDGETS = {"small-prop":1500,"medium-prop":6000,"vehicle":9000,"building":12000,"character":8000,"rock":400};
const SEGMENTS = {"small":8,"default":12,"large":16};

// Bevel radius for roundedBoxGeo: ratio of the smallest dimension (style range 0.06-0.12).
function bevel(w, h, d, ratio = 0.09) {
  return Math.min(w, h, d) * ratio;
}

// One shared material per role. Variants (e.g. structure-gray) take an explicit colour token.
function styleMaterials() {
  const m = {"matte-environment":{"description":"Terrain, rocks, craters, mountains. Fully matte, no reflections.","colors":["regolith-mid","regolith-light","shadow-plum"],"roughness":0.95,"metalness":0},"smooth-structure":{"description":"Buildings, modules, vehicles, suits, crates. Clean satin finish, never mirror-like.","colors":["structure-white","structure-gray"],"roughness":0.55,"metalness":0.05},"accent-paint":{"description":"Non-glowing orange colour blocking: side panels, crate faces, dome base band, suit pads, wheel hubs.","colors":["accent-orange"],"roughness":0.6,"metalness":0},"dark-trim":{"description":"Tyres, recesses, joints, vents.","colors":["trim-dark"],"roughness":0.85,"metalness":0},"emissive-warm":{"description":"Door frames, window strips, headlights. Selected surfaces only.","colors":["accent-orange"],"emissive":"accent-orange","emissiveIntensity":1.6,"roughness":0.5,"metalness":0},"emissive-cool":{"description":"Beacons, indicators, screens. Smaller and rarer than warm lights.","colors":["accent-cyan","accent-blue"],"emissive":"accent-cyan","emissiveIntensity":1.4,"roughness":0.5,"metalness":0},"glass":{"description":"Greenhouse domes, module windows. Light tint, soft highlight, see-through.","colors":["glass-tint"],"roughness":0.15,"metalness":0,"opacity":0.35},"visor":{"description":"Helmet visors and vehicle windshields. Opaque near-black, glossy, shows a soft highlight.","colors":["space-deep"],"roughness":0.12,"metalness":0.1},"solar-cell":{"description":"Solar panel cell faces. Deep blue, semi-gloss, framed by structure-white grid bars.","colors":["cell-blue"],"roughness":0.35,"metalness":0.1}};
  const make = (role, colorToken) => {
    const spec = m[role];
    const color = PALETTE[colorToken ?? spec.colors[0]];
    const name = colorToken && colorToken !== spec.colors[0] ? role + ':' + colorToken : role;
    if (role === 'glass') return glassMaterial(color, { opacity: spec.opacity, roughness: spec.roughness, metalness: spec.metalness, name });
    const opts = { roughness: spec.roughness, metalness: spec.metalness, name };
    if (spec.emissive) Object.assign(opts, { emissive: PALETTE[spec.emissive], emissiveIntensity: spec.emissiveIntensity });
    return gameMaterial(color, opts);
  };
  return {
    rock: make('matte-environment'),
    rockLight: make('matte-environment', 'regolith-light'),
    rockShadow: make('matte-environment', 'shadow-plum'),
    panel: make('smooth-structure'),
    panelGray: make('smooth-structure', 'structure-gray'),
    accent: make('accent-paint'),
    trim: make('dark-trim'),
    glowWarm: make('emissive-warm'),
    glowCool: make('emissive-cool'),
    glowBlue: make('emissive-cool', 'accent-blue'),
    glass: make('glass'),
    visor: make('visor'),
    solarCell: make('solar-cell'),
  };
}
// ---- end style header ----

const meta = {
  name: 'greenhouse-dome',
  role: 'building',
  reference: 'models and assets images/phase-5/greenhouse-dome.png'
};

function normalizeVec(v) {
  const len = Math.hypot(v[0], v[1], v[2]);
  if (len < 1e-6) return [0, 1, 0];
  return [v[0] / len, v[1] / len, v[2] / len];
}

function makeStrut(name, pA, pB, radius, mat, parent, segs = 6) {
  const dx = pB[0] - pA[0];
  const dy = pB[1] - pA[1];
  const dz = pB[2] - pA[2];
  const len = Math.hypot(dx, dy, dz);
  if (len < 1e-4) return null;
  const center = [(pA[0] + pB[0]) / 2, (pA[1] + pB[1]) / 2, (pA[2] + pB[2]) / 2];
  const normal = [dx, dy, dz];
  const geo = cylinderOnAxis(center, normal, radius, len, { segments: segs });
  return createPart(name, geo, mat, { parent });
}

function makeHub(name, p, normal, radius, height, mat, parent, segs = 8) {
  const norm = normalizeVec(normal);
  const center = [
    p[0] + norm[0] * (height * 0.4),
    p[1] + norm[1] * (height * 0.4),
    p[2] + norm[2] * (height * 0.4)
  ];
  const geo = cylinderOnAxis(center, norm, radius, height, { segments: segs });
  return createPart(name, geo, mat, { parent });
}

function build() {
  const root = createRoot('greenhouse-dome');
  const m = styleMaterials();

  // Custom tokens for greenhouse interior
  const glowMagenta = gameMaterial(PALETTE['grow-magenta'], {
    emissive: PALETTE['grow-magenta'],
    emissiveIntensity: 1.6,
    roughness: 0.5,
    metalness: 0,
    name: 'emissive-magenta'
  });

  const plantGreen = gameMaterial(PALETTE['plant-green'], {
    roughness: 0.85,
    metalness: 0,
    name: 'plant-foliage'
  });

  // Base parameters
  const BASE_SECTORS = 12;
  const R_BASE = 2.95;
  const R_COLLAR = 2.85;
  const Y_GROUND = 0;
  const Y_BASE = 0.82;
  const Y_COLLAR = 0.94;

  // -------------------------------------------------------------------------
  // 1. BASE SKIRT & FOUNDATION RING
  // -------------------------------------------------------------------------
  const basePivot = createPivot('BaseSkirt', [0, 0, 0], root);

  // Interior floor slab (Y = 0.42)
  createPart('InteriorFloor', cylinderGeo(R_COLLAR * 0.98, R_COLLAR * 0.98, 0.12, 16), m.panelGray, {
    position: [0, 0.42, 0],
    parent: basePivot
  });

  // Inner subfloor/ground ring
  createPart('SubFloor', cylinderGeo(R_BASE * 1.01, R_BASE * 1.01, 0.08, 16), m.trim, {
    position: [0, 0.04, 0],
    parent: basePivot
  });

  // 12 Skirt wall panels and vertical slate pillars
  // Sector 0 is centered at +X (door opening: angle -15 deg to +15 deg)
  const dTheta = (2 * Math.PI) / BASE_SECTORS;

  for (let i = 0; i < BASE_SECTORS; i++) {
    const angle0 = i * dTheta - dTheta / 2;
    const angle1 = i * dTheta + dTheta / 2;
    const midAngle = i * dTheta;

    // Boundary vertex between sector i and i-1
    const pVertex = [R_BASE * Math.cos(angle0), Y_BASE * 0.5, R_BASE * Math.sin(angle0)];

    // Boundary vertical pillar (slate grey)
    // Don't place pillars blocking the center of the door
    createPart(`Pillar_${i}`, boxGeo(0.18, Y_BASE, 0.20), m.panelGray, {
      position: [R_BASE * Math.cos(angle0), Y_BASE * 0.5, R_BASE * Math.sin(angle0)],
      rotation: [0, -angle0 * 180 / Math.PI, 0],
      parent: basePivot
    });

    // Top chamfer cap on pillar
    createPart(`PillarCap_${i}`, cylinderGeo(0.12, 0.15, Y_COLLAR - Y_BASE, 6), m.panelGray, {
      position: [R_BASE * 0.98 * Math.cos(angle0), (Y_BASE + Y_COLLAR) * 0.5, R_BASE * 0.98 * Math.sin(angle0)],
      rotation: [0, -angle0 * 180 / Math.PI, 0],
      parent: basePivot
    });

    // Sector 0 is the front entrance portal (skip wall panels here)
    if (i === 0) continue;

    // Wall panel between angle0 and angle1
    const panelMidR = R_BASE * 0.97;
    const panelPos = [panelMidR * Math.cos(midAngle), Y_BASE * 0.5, panelMidR * Math.sin(midAngle)];
    const chordLen = 2 * R_BASE * Math.sin(dTheta / 2) * 0.94;

    // Alternate panels: ivory structure panels with vibrant orange vertical bands
    // Sectors 1 and 11 (flanking the portal) have bold orange central stripes
    const hasOrangeStripe = (i === 1 || i === 11 || i === 3 || i === 5 || i === 7 || i === 9);

    // Main ivory skirt wall section
    createPart(`WallPanel_${i}`, boxGeo(0.16, Y_BASE * 0.94, chordLen), m.panel, {
      position: panelPos,
      rotation: [0, -midAngle * 180 / Math.PI, 0],
      parent: basePivot
    });

    // Beveled top collar segment
    const collarPos = [R_COLLAR * 0.98 * Math.cos(midAngle), (Y_BASE + Y_COLLAR) * 0.5, R_COLLAR * 0.98 * Math.sin(midAngle)];
    createPart(`CollarSegment_${i}`, boxGeo(0.18, Y_COLLAR - Y_BASE, chordLen * 0.96), m.panel, {
      position: collarPos,
      rotation: [0, -midAngle * 180 / Math.PI, 0],
      parent: basePivot
    });

    // Orange accent stripe on designated panels
    if (hasOrangeStripe) {
      const stripeWidth = (i === 1 || i === 11) ? chordLen * 0.55 : chordLen * 0.45;
      createPart(`WallOrange_${i}`, boxGeo(0.17, Y_BASE * 0.92, stripeWidth), m.accent, {
        position: [panelPos[0] * 1.005, panelPos[1], panelPos[2] * 1.005],
        rotation: [0, -midAngle * 180 / Math.PI, 0],
        parent: basePivot
      });
    }
  }

  // -------------------------------------------------------------------------
  // 2. FRONT ENTRANCE PORTAL & ACCESS STEPS (+X)
  // -------------------------------------------------------------------------
  const portalPivot = createPivot('EntrancePortal', [0, 0, 0], root);

  // Outer slate archway frame (+X edge, Y from 0.45 to 2.45)
  // Left and right vertical jambs
  const portalX = 2.85;
  const jambZ = 0.72;
  const jambH = 1.70;
  const jambY = 0.45 + jambH / 2;

  // Outer slate posts
  createPart('PortalPost_L', boxGeo(0.36, jambH, 0.24), m.panelGray, {
    position: [portalX, jambY, jambZ],
    parent: portalPivot
  });
  createPart('PortalPost_R', boxGeo(0.36, jambH, 0.24), m.panelGray, {
    position: [portalX, jambY, -jambZ],
    parent: portalPivot
  });

  // Top lintel with chamfered 45-deg top shoulders
  const lintelY = 0.45 + jambH + 0.16;
  createPart('PortalLintel', boxGeo(0.36, 0.32, 1.44), m.panelGray, {
    position: [portalX, lintelY, 0],
    parent: portalPivot
  });

  // Top chamfer corner pads for the slate arch
  createPart('PortalChamfer_L', boxGeo(0.34, 0.22, 0.22), m.panelGray, {
    position: [portalX, lintelY - 0.05, jambZ - 0.08],
    rotation: [45, 0, 0],
    parent: portalPivot
  });
  createPart('PortalChamfer_R', boxGeo(0.34, 0.22, 0.22), m.panelGray, {
    position: [portalX, lintelY - 0.05, -jambZ + 0.08],
    rotation: [-45, 0, 0],
    parent: portalPivot
  });

  // Horizontal cyan indicator light over the portal lintel
  createPart('PortalCyanLight', boxGeo(0.08, 0.09, 0.42), m.glowCool, {
    position: [portalX + 0.16, lintelY + 0.04, 0],
    parent: portalPivot
  });

  // Mars orange inner chamfered frame lining the archway
  const innerPostH = 1.58;
  const innerPostY = 0.45 + innerPostH / 2;
  const innerJambZ = 0.54;
  createPart('InnerOrangeJamb_L', boxGeo(0.32, innerPostH, 0.12), m.accent, {
    position: [portalX + 0.03, innerPostY, innerJambZ],
    parent: portalPivot
  });
  createPart('InnerOrangeJamb_R', boxGeo(0.32, innerPostH, 0.12), m.accent, {
    position: [portalX + 0.03, innerPostY, -innerJambZ],
    parent: portalPivot
  });
  createPart('InnerOrangeHeader', boxGeo(0.32, 0.14, 1.10), m.accent, {
    position: [portalX + 0.03, 0.45 + innerPostH + 0.07, 0],
    parent: portalPivot
  });

  // Inner orange chamfer corners
  createPart('InnerOrangeCorner_L', boxGeo(0.30, 0.16, 0.16), m.accent, {
    position: [portalX + 0.03, 0.45 + innerPostH, innerJambZ - 0.06],
    rotation: [45, 0, 0],
    parent: portalPivot
  });
  createPart('InnerOrangeCorner_R', boxGeo(0.30, 0.16, 0.16), m.accent, {
    position: [portalX + 0.03, 0.45 + innerPostH, -innerJambZ + 0.06],
    rotation: [-45, 0, 0],
    parent: portalPivot
  });

  // Clear glass sliding doors in the portal
  createPart('PortalGlassDoor', boxGeo(0.04, 1.52, 0.94), m.glass, {
    position: [portalX - 0.02, 0.45 + 0.76, 0],
    parent: portalPivot
  });

  // Vertical dark door handles (attached to orange inner jambs)
  createPart('DoorHandle_L', boxGeo(0.06, 0.35, 0.04), m.trim, {
    position: [portalX + 0.06, 0.45 + 0.75, 0.46],
    parent: portalPivot
  });
  createPart('DoorHandle_R', boxGeo(0.06, 0.35, 0.04), m.trim, {
    position: [portalX + 0.06, 0.45 + 0.75, -0.46],
    parent: portalPivot
  });

  // Access steps leading down to Y = 0
  const stepW = 1.08;
  createPart('Step_1', boxGeo(0.24, 0.14, stepW), m.panel, {
    position: [portalX + 0.14, 0.35, 0],
    parent: portalPivot
  });
  createPart('Step_2', boxGeo(0.24, 0.14, stepW), m.panel, {
    position: [portalX + 0.36, 0.21, 0],
    parent: portalPivot
  });
  createPart('Step_3', boxGeo(0.26, 0.14, stepW), m.panel, {
    position: [portalX + 0.60, 0.07, 0],
    parent: portalPivot
  });

  // Flanking slate cheek walls / curbs along the steps
  createPart('StepCheek_L', boxGeo(0.74, 0.46, 0.22), m.panelGray, {
    position: [portalX + 0.37, 0.23, stepW / 2 + 0.11],
    parent: portalPivot
  });
  createPart('StepCheek_R', boxGeo(0.74, 0.46, 0.22), m.panelGray, {
    position: [portalX + 0.37, 0.23, -stepW / 2 - 0.11],
    parent: portalPivot
  });

  // Chamfered slope pads on cheek walls
  createPart('StepCheekPad_L', boxGeo(0.32, 0.16, 0.20), m.panelGray, {
    position: [portalX + 0.65, 0.15, stepW / 2 + 0.11],
    rotation: [0, 0, 30],
    parent: portalPivot
  });
  createPart('StepCheekPad_R', boxGeo(0.32, 0.16, 0.20), m.panelGray, {
    position: [portalX + 0.65, 0.15, -stepW / 2 - 0.11],
    rotation: [0, 0, 30],
    parent: portalPivot
  });

  // -------------------------------------------------------------------------
  // 3. GEODESIC DOME & GLASS SHELL (Semantic 'roof' node)
  // -------------------------------------------------------------------------
  const roof = createPivot('roof', [0, 0, 0], root);

  // Transparent warm tinted glass hemisphere generated via lathe profile
  // Smoothly curves from Y_COLLAR (0.94 m) up to apex (3.92 m) without extending below base
  const glassProfile = [];
  const PROFILE_STEPS = 16;
  const glassDomeRadius = 2.82;
  const glassDomeH = 2.96;
  for (let s = 0; s <= PROFILE_STEPS; s++) {
    const angle = (s / PROFILE_STEPS) * (Math.PI / 2);
    const r = glassDomeRadius * Math.cos(angle);
    const y = Y_COLLAR + glassDomeH * Math.sin(angle);
    glassProfile.push([r, y]);
  }
  const glassGeo = lathe(glassProfile, 24);
  createPart('DomeGlassShell', glassGeo, m.glass, {
    position: [0, 0, 0],
    parent: roof
  });

  // Geodesic Vertices:
  // Ring 0 (Dome base, Y = 0.96)
  const ring0 = [];
  const R0 = 2.82;
  const Y0 = 0.96;
  for (let i = 0; i < BASE_SECTORS; i++) {
    const a = i * dTheta;
    ring0.push([R0 * Math.cos(a), Y0, R0 * Math.sin(a)]);
  }

  // Ring 1 (Mid-lower dome, Y = 1.95)
  const ring1 = [];
  const R1 = 2.65;
  const Y1 = 1.95;
  for (let i = 0; i < BASE_SECTORS; i++) {
    const a = (i + 0.5) * dTheta;
    ring1.push([R1 * Math.cos(a), Y1, R1 * Math.sin(a)]);
  }

  // Ring 2 (Mid-upper dome, Y = 2.92)
  const ring2 = [];
  const R2 = 2.05;
  const Y2 = 2.92;
  for (let i = 0; i < BASE_SECTORS; i++) {
    const a = i * dTheta;
    ring2.push([R2 * Math.cos(a), Y2, R2 * Math.sin(a)]);
  }

  // Ring 3 (Upper dome crown, Y = 3.60)
  const ring3 = [];
  const R3 = 1.15;
  const Y3 = 3.60;
  for (let k = 0; k < 6; k++) {
    const a = (k + 0.5) * ((2 * Math.PI) / 6);
    ring3.push([R3 * Math.cos(a), Y3, R3 * Math.sin(a)]);
  }

  // Ring 4 (Apex, Y = 3.92)
  const apex = [0, 3.92, 0];

  const strutR = 0.038;
  const hubR = 0.095;
  const hubH = 0.045;

  // Struts & Hubs Generation
  // 1. Ring 0 horizontal struts & hubs (skip door opening at front between sector 11 and 1)
  for (let i = 0; i < BASE_SECTORS; i++) {
    const nextI = (i + 1) % BASE_SECTORS;
    if (i !== 0 && i !== 11) {
      makeStrut(`Strut_R0_${i}`, ring0[i], ring0[nextI], strutR, m.panel, roof);
    }
    // Hub plate at Ring 0 vertices
    if (i !== 0) {
      makeHub(`Hub_R0_${i}`, ring0[i], [ring0[i][0], 0.2, ring0[i][2]], hubR, hubH, m.panelGray, roof);
    }
  }

  // 2. Ring 1 horizontal struts & hubs
  for (let i = 0; i < BASE_SECTORS; i++) {
    const nextI = (i + 1) % BASE_SECTORS;
    makeStrut(`Strut_R1_${i}`, ring1[i], ring1[nextI], strutR, m.panel, roof);
    makeHub(`Hub_R1_${i}`, ring1[i], [ring1[i][0], 0.5, ring1[i][2]], hubR, hubH, m.panelGray, roof);
  }

  // 3. Diagonal struts between Ring 0 and Ring 1 (forming alternating triangles)
  for (let i = 0; i < BASE_SECTORS; i++) {
    const nextI = (i + 1) % BASE_SECTORS;
    // Omit struts crossing directly over the door opening
    const crossesDoor1 = (i === 0 || i === 11);
    if (!crossesDoor1) {
      makeStrut(`Diag_0_1_A_${i}`, ring0[i], ring1[i], strutR, m.panel, roof);
    }
    const crossesDoor2 = (i === 11 || nextI === 0);
    if (!crossesDoor2) {
      makeStrut(`Diag_0_1_B_${i}`, ring0[nextI], ring1[i], strutR, m.panel, roof);
    }
  }

  // 4. Ring 2 horizontal struts & hubs
  for (let i = 0; i < BASE_SECTORS; i++) {
    const nextI = (i + 1) % BASE_SECTORS;
    makeStrut(`Strut_R2_${i}`, ring2[i], ring2[nextI], strutR, m.panel, roof);
    makeHub(`Hub_R2_${i}`, ring2[i], [ring2[i][0], 0.8, ring2[i][2]], hubR, hubH, m.panelGray, roof);
  }

  // 5. Diagonal struts between Ring 1 and Ring 2
  for (let i = 0; i < BASE_SECTORS; i++) {
    const prevI = (i - 1 + BASE_SECTORS) % BASE_SECTORS;
    makeStrut(`Diag_1_2_A_${i}`, ring1[i], ring2[i], strutR, m.panel, roof);
    makeStrut(`Diag_1_2_B_${i}`, ring1[i], ring2[prevI], strutR, m.panel, roof);
  }

  // 6. Ring 3 horizontal struts & hubs
  for (let k = 0; k < 6; k++) {
    const nextK = (k + 1) % 6;
    makeStrut(`Strut_R3_${k}`, ring3[k], ring3[nextK], strutR, m.panel, roof);
    makeHub(`Hub_R3_${k}`, ring3[k], [ring3[k][0], 1.2, ring3[k][2]], hubR, hubH, m.panelGray, roof);
  }

  // 7. Diagonals between Ring 2 (12 vertices) and Ring 3 (6 vertices)
  for (let i = 0; i < BASE_SECTORS; i++) {
    const k = Math.floor(i / 2);
    makeStrut(`Diag_2_3_${i}`, ring2[i], ring3[k], strutR, m.panel, roof);
  }

  // 8. Struts from Ring 3 to Apex
  for (let k = 0; k < 6; k++) {
    makeStrut(`Strut_Crown_${k}`, ring3[k], apex, strutR, m.panel, roof);
  }

  // Apex Hub Plate (octagonal slate cap at peak)
  createPart('ApexHubPlate', cylinderGeo(0.24, 0.28, 0.08, 8), m.panelGray, {
    position: apex,
    parent: roof
  });
  createPart('ApexHubButton', cylinderGeo(0.12, 0.16, 0.04, 8), m.panel, {
    position: [apex[0], apex[1] + 0.05, apex[2]],
    parent: roof
  });

  // -------------------------------------------------------------------------
  // 4. INTERIOR GROW TRAYS & CANOPY LIGHTS
  // -------------------------------------------------------------------------
  const interiorPivot = createPivot('Interior', [0, 0, 0], root);

  function createGrowTray(id, pos, rotY) {
    const trayRoot = createPivot(`tray_${id}`, pos, interiorPivot);
    trayRoot.rotation.y = rotY * Math.PI / 180;

    // Trough body (slate gray)
    const tW = 0.70;
    const tH = 0.36;
    const tL = 1.45;
    createPart(`TrayBody_${id}`, boxGeo(tW, tH, tL), m.panelGray, {
      position: [0, tH / 2, 0],
      parent: trayRoot
    });

    // Orange accent face panel facing outward (+X in tray coords)
    createPart(`TrayAccent_${id}`, boxGeo(0.04, tH * 0.70, tL * 0.75), m.accent, {
      position: [tW / 2 + 0.015, tH / 2, 0],
      parent: trayRoot
    });

    // Dark soil regolith bed
    createPart(`SoilBed_${id}`, boxGeo(tW * 0.82, 0.06, tL * 0.88), m.rockShadow, {
      position: [0, tH + 0.01, 0],
      parent: trayRoot
    });

    // Clustered stylized plant foliage
    const plantCount = 5;
    for (let p = 0; p < plantCount; p++) {
      const zOffset = (p - 2) * (tL * 0.16);
      const plantPivot = createPivot(`Plant_${id}_${p}`, [0, tH + 0.04, zOffset], trayRoot);

      // Rounded plant leaf cluster
      createPart(`LeafCenter_${id}_${p}`, sphereGeo(0.11, 6, 6), plantGreen, {
        position: [0, 0.10, 0],
        scale: [1.1, 0.75, 1.1],
        parent: plantPivot
      });
      createPart(`LeafLeft_${id}_${p}`, sphereGeo(0.09, 5, 5), plantGreen, {
        position: [-0.08, 0.08, 0.06],
        scale: [1.2, 0.6, 0.9],
        rotation: [15, 30, 20],
        parent: plantPivot
      });
      createPart(`LeafRight_${id}_${p}`, sphereGeo(0.09, 5, 5), plantGreen, {
        position: [0.08, 0.08, -0.06],
        scale: [1.2, 0.6, 0.9],
        rotation: [-15, -30, -20],
        parent: plantPivot
      });
    }

    // Overhead LED Canopy Light
    // Support rods rising from tray rear
    const rodH = 0.95;
    const rodZ1 = tL * 0.35;
    const rodZ2 = -tL * 0.35;
    createPart(`CanopyRodA_${id}`, cylinderGeo(0.02, 0.02, rodH, 6), m.trim, {
      position: [-tW * 0.38, tH + rodH / 2, rodZ1],
      parent: trayRoot
    });
    createPart(`CanopyRodB_${id}`, cylinderGeo(0.02, 0.02, rodH, 6), m.trim, {
      position: [-tW * 0.38, tH + rodH / 2, rodZ2],
      parent: trayRoot
    });

    // Horizontal arm hanging over the tray
    const armY = tH + rodH;
    createPart(`CanopyArmA_${id}`, boxGeo(tW * 0.40, 0.03, 0.03), m.trim, {
      position: [-tW * 0.18, armY, rodZ1],
      parent: trayRoot
    });
    createPart(`CanopyArmB_${id}`, boxGeo(tW * 0.40, 0.03, 0.03), m.trim, {
      position: [-tW * 0.18, armY, rodZ2],
      parent: trayRoot
    });

    // LED canopy light hood fixture (dark slate)
    createPart(`LightHood_${id}`, boxGeo(0.30, 0.07, tL * 0.82), m.panelGray, {
      position: [0, armY - 0.04, 0],
      parent: trayRoot
    });

    // Glowing magenta LED panel underneath hood
    createPart(`MagentaLED_${id}`, boxGeo(0.24, 0.02, tL * 0.76), glowMagenta, {
      position: [0, armY - 0.08, 0],
      parent: trayRoot
    });

    return trayRoot;
  }

  // Place the 3 grow trays (Tray 1 center back, Tray 2 left, Tray 3 right)
  createGrowTray(1, [-1.20, 0.45, 0], 180);
  createGrowTray(2, [0.35, 0.45, 1.40], -45);
  createGrowTray(3, [0.35, 0.45, -1.40], 45);

  // Floating Station View info anchor
  createPivot('info_anchor', [0, 4.15, 0], root);

  // Define Category Budget
  defineBudget({ triangles: BUDGETS['building'] }, root);

  return root;
}
